// Generates functions/src/instagram/aiRelease.generated.ts: the app version and the "What's new" notes of the latest
// releases (docs/release/<version>-notes.txt, <en-US> block), so the Instagram DM agent can describe current features
// and recent updates. Only versions live on Google Play count: docs/release/published.txt holds the latest published
// version (bump it when a release reaches production), so a built-but-unreleased version is never described to people.
// Runs from `npm run build` in functions/; the generated file is committed as a fallback.
const fs = require("fs"), path = require("path");
const root = path.join(__dirname, "../..");
const gradle = fs.readFileSync(path.join(root, "app/build.gradle.kts"), "utf8");
const built = (/versionName\s*=\s*"([^"]+)"/.exec(gradle) || [])[1] || "unknown";
const dir = path.join(root, "docs/release");
const publishedFile = path.join(dir, "published.txt");
const version = fs.existsSync(publishedFile) ? fs.readFileSync(publishedFile, "utf8").trim() : built;
const cmp = (a, b) => a.localeCompare(b, undefined, { numeric: true });
const notes = fs.readdirSync(dir).filter((f) => /^\d+\.\d+\.\d+-notes\.txt$/.test(f))
  .filter((f) => cmp(f.replace(/-notes\.txt$/, ""), version) <= 0)
  .sort(cmp).slice(-4).reverse()
  .map((f) => {
    const txt = fs.readFileSync(path.join(dir, f), "utf8");
    const m = /<en-US>\s*([\s\S]*?)\s*<\/en-US>/.exec(txt);
    return m ? m[1].trim() : "";
  }).filter(Boolean);
const body = `RELEASE AND LATEST UPDATES (generated from docs/release; current Google Play version ${version})\n` +
  notes.map((n) => n.replace(/^What's new in ProHost/i, "Update").trim()).join("\n\n");
const out = `// GENERATED by scripts/website/gen-agent-release.js — do not edit by hand.\nexport const APP_VERSION = ${JSON.stringify(version)};\nexport const RELEASE_KNOWLEDGE = ${JSON.stringify(body)};\n`;
fs.writeFileSync(path.join(root, "functions/src/instagram/aiRelease.generated.ts"), out);
console.log(`agent release knowledge: version ${version} (app built as ${built}), ${notes.length} release note block(s)`);
